# ai-agents/metrics/survey/questions.yaml
# Builds the October form and the December one. Don't edit the questions between the two runs.
group_by: team        # FE, BE, DevOps, Data Science, Other. No names and no emails are collected.
min_group_size: 5     # smaller teams fold into Other when we report
scales:
  hours: ["0", "under 1 h", "1-3 h", "3-6 h", "more than 6 h"]
  agree: ["1 strongly disagree", "2", "3", "4", "5 strongly agree"]
questions:
  - { id: time_saved,       scale: hours, text: "In a normal week, how much time do AI tools save you?" }
  - { id: lost_meetings,    scale: hours, text: "In a normal week, how much time do you lose to meetings that didn't need you?" }
  - { id: lost_interrupts,  scale: hours, text: "In a normal week, how much time do you lose to interruptions and switching tasks?" }
  - { id: lost_builds,      scale: hours, text: "In a normal week, how much time do you lose waiting for builds, tests and CI?" }
  - { id: lost_review,      scale: hours, text: "In a normal week, how much time do you lose waiting for code review?" }
  - { id: lost_setup,       scale: hours, text: "In a normal week, how much time do you lose to a broken or slow dev setup?" }
  - { id: lost_finding,     scale: hours, text: "In a normal week, how much time do you lose looking for information?" }
  - { id: confident_change, scale: agree, text: "I feel confident changing code in a part of the product I don't know well." }
  - { id: confident_ci,     scale: agree, text: "When CI is green, I trust that my change works." }
  - { id: biggest_drag,     scale: text,  text: "What one thing slows you down the most?" }

// ai-agents/metrics/src/github.ts
// Pull fcp PRs with the timeline facts the delivery metrics need.
import { graphql } from "./gh.js"; // fetch POST https://api.github.com/graphql with a read-only App token
import type { PrSearch } from "./types.js"; // the shape of this query's result

const QUERY = `
query($q: String!, $after: String) {
  search(query: $q, type: ISSUE, first: 50, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes { ... on PullRequest {
      number createdAt mergedAt bodyText author { login }
      commits(first: 100) { nodes { commit { authoredDate message } } }
      timelineItems(itemTypes: [READY_FOR_REVIEW_EVENT, PULL_REQUEST_REVIEW], first: 50) {
        nodes { __typename
          ... on ReadyForReviewEvent { createdAt }
          ... on PullRequestReview { createdAt state author { login __typename } } } }
    } }
  }
}`;

/** One week per query (GitHub search stops at 1000 results). Run again with field = "merged". */
export async function* pullRequests(repo: string, weekStart: string, weekEnd: string, field: "created" | "merged" = "created") {
  const q = `repo:${repo} is:pr ${field}:${weekStart}..${weekEnd}`;
  let after: string | null = null;
  do {
    const { search }: PrSearch = await graphql(QUERY, { q, after });
    for (const { commits, timelineItems, ...pr } of search.nodes) {
      const done = commits.nodes.map((n) => n.commit);
      const firstCommitAt = done.map((c) => c.authoredDate).sort()[0] ?? pr.createdAt; // ISO strings sort by time
      const aiTrailer = pr.bodyText.includes("Generated with Claude Code") || done.some((c) => c.message.includes("Co-Authored-By: Claude"));
      yield { ...pr, firstCommitAt, aiTrailer, timeline: timelineItems.nodes };
    }
    after = search.pageInfo.hasNextPage ? search.pageInfo.endCursor : null;
  } while (after);
}

