// ai-agents/metrics/src/ci.ts
// Hours fcp main stays red, from the required unit-test jobs only (I&T flakiness is G7's problem).
import { rest, restPages } from "./gh.js"; // small fetch helpers with the read-only App token; restPages follows Link: next
import type { Job, WorkflowRun } from "./types.js";
const REQUIRED: Record<string, string[]> = { // workflow file -> job names (the second one is the name before G0's rename)
  "cloud-ci.yml": ["Cloud Unit Tests", "Unit Tests"],
  "client-ci.yml": ["Client Unit Tests", "Unit Tests"],
  "frontend-ci.yaml": ["Frontend Unit Tests", "Unit Tests"],
};
export type Result = { workflow: string; at: Date; ok: boolean };
export async function* mainResults(repo: string, since: string): AsyncGenerator<Result> {
  for (const [workflow, names] of Object.entries(REQUIRED)) {
    const query = { branch: "main", status: "completed", created: `>=${since}` };
    for await (const run of restPages<WorkflowRun>(`/repos/${repo}/actions/workflows/${workflow}/runs`, query)) {
      const { jobs } = await rest<{ jobs: Job[] }>(`/repos/${repo}/actions/runs/${run.id}/jobs`);
      const job = jobs.find((j) => names.includes(j.name));
      if (job?.completed_at && (job.conclusion === "success" || job.conclusion === "failure")) {
        yield { workflow, at: new Date(job.completed_at), ok: job.conclusion === "success" };
      }
    }
  }
}

/** main is red while any required job's latest result is a failure; overlaps count once. */
export function redHours(results: Result[]): number {
  const state = new Map<string, boolean>();
  let redSince: Date | undefined, total = 0;
  for (const { workflow, at, ok } of results.toSorted((a, b) => a.at.getTime() - b.at.getTime())) {
    state.set(workflow, ok);
    const redNow = [...state.values()].includes(false);
    if (redNow && !redSince) redSince = at;
    else if (!redNow && redSince) { total += (at.getTime() - redSince.getTime()) / 3_600_000; redSince = undefined; }
  }
  return total;
}

// ai-agents/metrics/src/compute.ts
// Weekly, team-level delivery metrics. Nothing here is ever written per person.
import { days, hours, median, quantile } from "./stats.js"; // ISO timestamps in, numbers out; quantile as Python's statistics
import type { Fix, MergedPr, Point, PullRequest } from "./types.js";

/** Ready for review (or opened, if never a draft) to the first review by another person. */
export function reviewWaitHours(pr: PullRequest): number | undefined {
  const ready = pr.timeline.find((e) => e.__typename === "ReadyForReviewEvent")?.createdAt ?? pr.createdAt;
  const first = pr.timeline.find((e) => e.__typename === "PullRequestReview"
    && e.author?.__typename === "User" && e.author.login !== pr.author.login)?.createdAt;
  return first ? hours(ready, first) : undefined;
}

export const leadTimeHours = (pr: PullRequest) => (pr.mergedAt ? hours(pr.firstCommitAt, pr.mergedAt) : undefined);

/** A revert, hotfix or Bug fix within 14 days on the same lines (G2's miner does the blame). */
export const changeFailed = (pr: MergedPr, fixes: Fix[]) =>
  fixes.some((f) => f.introducedBy === pr.number && days(pr.mergedAt, f.mergedAt) <= 14);

export function* weeklyPoints(prs: PullRequest[], fixes: Fix[], teamOf: (pr: PullRequest) => string, weekTs: number): Generator<Point> {
  const byTeam = new Map<string, PullRequest[]>();
  for (const pr of prs) { // agent PRs count for the requester's team; teams under 3 people map to "other"
    byTeam.set(teamOf(pr), [...(byTeam.get(teamOf(pr)) ?? []), pr]);
  }
  for (const [team, items] of byTeam) {
    const waits = items.map(reviewWaitHours).filter((w) => w !== undefined);
    if (waits.length >= 2) {
      yield ["delivery_review_wait_hours", { team, q: "p50" }, median(waits), weekTs];
      yield ["delivery_review_wait_hours", { team, q: "p85" }, quantile(waits, 0.85), weekTs];
    }
    const merged = items.filter((p): p is MergedPr => p.mergedAt !== null);
    yield ["delivery_merged_prs", { team }, merged.length, weekTs];
    yield ["delivery_failed_changes", { team }, merged.filter((p) => changeFailed(p, fixes)).length, weekTs];
  }
}

// ai-agents/metrics/src/lenses.ts
// DX's three lenses for one team and week, side by side. Never a per-person number.
// Keys stay snake_case: each one becomes a delivery_lens_<key> series.
import type { AgentRun, Gateway, Jira, Otel, PullRequest, Week } from "./types.js";

export const share = <T>(items: T[], predicate: (item: T) => boolean): number =>
  items.length ? items.filter(predicate).length / items.length : 0;

export const utilization = async (week: Week, otel: Otel, prs: PullRequest[], jira: Jira) => ({
  weekly_ai_users: await otel.distinct("user_hash", week), // salted hash from the collector; no emails
  pr_ai_share: share(prs, (pr) => pr.aiTrailer), // Co-Authored-By: Claude / "Generated with Claude Code"
  tasks_to_agents: (await jira.count('assignee = "Nova"', week)) + (await jira.routineRuns(week)),
});

export const impact = (_week: Week, prs: PullRequest[], failed: Set<number>, agentRuns: AgentRun[]) => {
  const merged = prs.filter((pr) => pr.mergedAt);
  return {
    merged_prs: merged.length, // always shown next to change failure, never alone
    change_fail_pct: 100 * share(merged, (pr) => failed.has(pr.number)),
    // decide (Nir): proposal = the hours an engineer would need, stated in Nova's approved plan
    human_equivalent_hours: agentRuns.filter((run) => run.merged).reduce((sum, run) => sum + run.humanHours, 0),
  };
};

export const cost = async (week: Week, gateway: Gateway, otel: Otel, engineers: number, humanHours: number) => {
  const agentsUsd = await gateway.totalUsd(week); // ai_agents_llm_cost_usd_total
  const peopleUsd = await otel.costUsd(week); // claude_code_cost_usage_USD_total
  return {
    ai_spend_usd: agentsUsd + peopleUsd,
    ai_spend_per_engineer_usd: (agentsUsd + peopleUsd) / Math.max(engineers, 1), // a team average
    // The plan writes "hours / cost"; as a rate it is cost per hour. Confirm the wording with Nir.
    agent_usd_per_human_hour: humanHours ? agentsUsd / humanHours : null,
  };
};

// ai-agents/harness/src/telemetry.ts  (the harness itself is G3's)
import { readFileSync } from "node:fs";

// harness/package.json is one level above both src/ and dist/; its version changes on every harness release
const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as { version: string };
export const HARNESS_VERSION = pkg.version;
export const STEPS = ["ticket", "plan", "plan_ok", "vm", "build", "pr", "byte", "approve", "learn"] as const;
export type Step = (typeof STEPS)[number];
export interface RunTags { agent: string; jira: string; id: string }

/** Env for one Agent SDK session. Its OTel data and its gateway calls carry the same tags. */
export function stepEnv(run: RunTags, step: Step): Record<string, string> {
  if (!STEPS.includes(step)) throw new Error(`unknown step ${step}`);
  const tags = { agent: run.agent, jira: run.jira, run: run.id, step, "harness.version": HARNESS_VERSION };
  return {
    OTEL_RESOURCE_ATTRIBUTES: Object.entries(tags).map(([k, v]) => `${k}=${v}`).join(","),
    // agent, jira and run reach the gateway inside the run token; step and version ride on headers
    ANTHROPIC_CUSTOM_HEADERS: `x-ai-agents-step: ${step}\nx-ai-agents-harness: ${HARNESS_VERSION}`,
  };
}

// In a step (no maxTurns, no maxBudgetUsd, no taskBudget: the far-away backstop acts between turns, in the harness).
// options.env replaces the session's whole environment, so spread process.env (gateway URL and run token) first:
//   const options: Options = { model: route.model, effort: route.effort, env: { ...process.env, ...stepEnv(run, "build") } };
//   for await (const message of query({ prompt: task, options })) { ... }
// The Temporal workflow also sets search attributes Step and HarnessVersion for the same run
// (upsertSearchAttributes with typed keys from defineSearchAttributeKey).

// ai-agents/harness/src/label-run.ts  (npx tsx harness/src/label-run.ts <run-id> --failed-at ... --cause ...)
// Weekly run review: label a failed run with where it failed and which step should have caught it.
import { parseArgs } from "node:util";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { STEPS } from "./telemetry.js";

const CAUSES = ["too_many_tools", "bad_handoff", "contradicting_prompt", "missing_context",
  "flaky_environment", "model", "unknown"] as const;

const { values: a, positionals: [runId] } = parseArgs({
  allowPositionals: true,
  options: {
    "failed-at": { type: "string" },
    "should-have-caught": { type: "string" },
    cause: { type: "string" },
    note: { type: "string", default: "" }, // one line; no PHI, no secrets, no customer names
  },
});
const oneOf = (flag: string, value: string | undefined, allowed: readonly string[]): string => {
  if (!value || !allowed.includes(value)) throw new Error(`--${flag} must be one of: ${allowed.join(", ")}`);
  return value;
};
if (!runId) throw new Error("usage: label-run <run-id> --failed-at <step> --should-have-caught <step> --cause <cause>");

const label = { // the JSON keys are what the nightly job and the dashboards read
  run: runId, failed_at: oneOf("failed-at", a["failed-at"], STEPS),
  should_have_caught: oneOf("should-have-caught", a["should-have-caught"], STEPS),
  cause: oneOf("cause", a.cause, CAUSES), note: a.note, labelled_at: new Date().toISOString(),
};
await new S3Client({}).send(new PutObjectCommand({
  Bucket: "rhino-ai-agents-eval-results", Key: `runs/${runId}/label.json`,
  Body: JSON.stringify(label), ContentType: "application/json",
}));
console.log(`${runId}: failed at ${label.failed_at}, should have been caught at ${label.should_have_caught}`);

// ai-agents/metrics/src/quality.ts
// Step-quality numbers per agent and week, from run records. A gate's number, not a person's.
import type { Approval, ByteFinding, CheckRun, RunRecord } from "./types.js";

/** Tickets that passed the readiness check without being sent back / tickets assigned to Nova. */
export function readyOnFirstTry(runs: RunRecord[]): number | null {
  const assigned = runs.filter((r) => r.agent === "nova");
  return assigned.length ? assigned.filter((r) => r.readiness.sent_back === 0).length / assigned.length : null;
}

export function planAdherence(run: RunRecord, changedFiles: string[]) {
  const planned = new Set(run.plan.files);
  return {
    unplanned_files: new Set(changedFiles.filter((f) => !planned.has(f))).size,
    items_not_done: run.plan.items.filter((item) => !item.done).length,
  };
}

/** The required checks on the PR's first pushed commit were all green. */
export function firstPassGreen(checkRuns: CheckRun[], required: Set<string>): boolean {
  const first = checkRuns.reduce((a, b) => (b.started_at < a.started_at ? b : a)); // ISO strings compare by time
  return checkRuns.filter((c) => c.head_sha === first.head_sha && required.has(c.name)).every((c) => c.conclusion === "success");
}

export function caughtBeforePr(run: RunRecord, byteFindings: ByteFinding[]): number | null {
  const fixed = run.self_review.important_fixed; // from the self-review receipt in the PR
  const left = byteFindings.filter((f) => (f.severity === "HIGH" || f.severity === "MED") && f.new).length;
  return fixed + left ? fixed / (fixed + left) : null;
}

/** Plan or PR approvals given under 60 s after the request: run links for the weekly review. */
export function fastApprovals(approvals: Approval[], seconds = 60): string[] {
  return approvals.filter((a) => Date.parse(a.approved_at) - Date.parse(a.requested_at) < seconds * 1000).map((a) => a.run_url);
}

// ai-agents/metrics/src/survey-compare.ts  (npx tsx metrics/src/survey-compare.ts october.csv december.csv)
// October vs. December survey, team level only. Groups under 5 answers fold into 'Other'.
import { readFileSync } from "node:fs";
import { parse } from "csv-parse/sync"; // Google Forms answers can hold commas and quotes
import { median, quantile } from "./stats.js"; // quantile uses the same method as Python's statistics.quantiles

const MIN_GROUP = 5;
const HOURS: Record<string, number> = { "0": 0, "under 1 h": 0.5, "1-3 h": 2, "3-6 h": 4.5, "more than 6 h": 7 };
const QUESTIONS = ["time_saved", "lost_builds", "lost_review", "lost_setup", "lost_finding", "confident_change", "confident_ci"];
type Row = Record<string, string | undefined>;

function load(path: string): Map<string, Row[]> {
  const groups = new Map<string, Row[]>();
  for (const row of parse<Row>(readFileSync(path, "utf8"), { columns: true })) {
    const team = row.team ?? "Other";
    groups.set(team, [...(groups.get(team) ?? []), row]);
  }
  const keep = new Map([...groups].filter(([team, rows]) => rows.length >= MIN_GROUP && team !== "Other"));
  keep.set("Other", [...groups].filter(([team]) => !keep.has(team)).flatMap(([, rows]) => rows));
  return keep;
}

function summary(rows: Row[], question: string): string {
  const values = rows.flatMap((r) => { const a = r[question]; return a ? [HOURS[a] ?? Number(a[0])] : []; }); // agree: its digit
  if (values.length < MIN_GROUP) return "too few answers";
  const [mid, q1, q3] = [median(values), quantile(values, 0.25), quantile(values, 0.75)];
  return `median ${mid.toFixed(1)} (IQR ${q1.toFixed(1)}-${q3.toFixed(1)}, n=${values.length})`;
}
const [october, december] = [load(process.argv[2] ?? ""), load(process.argv[3] ?? "")];
for (const question of QUESTIONS) {
  for (const team of [...october.keys()].filter((t) => december.has(t)).sort()) {
    const oct = summary(october.get(team) ?? [], question), dec = summary(december.get(team) ?? [], question);
    console.log(`${question.padEnd(17)} ${team.padEnd(12)} Oct ${oct.padEnd(34)} Dec ${dec}`);
  }
}
